-- GENERATED by scripts/db_export_schema.py from the live database. Do not hand-edit.
CREATE OR REPLACE FUNCTION digest.member_match(p_phone text, p_dims text[] DEFAULT ARRAY['state'::text, 'category'::text, 'band'::text], p_limit integer DEFAULT 10, p_city text DEFAULT NULL::text, p_state text DEFAULT NULL::text, p_channel text DEFAULT NULL::text, p_category text DEFAULT NULL::text)
 RETURNS TABLE(full_name text, city text, state text, reasons text[])
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'digest', 'pg_temp'
AS $function$
declare
  v_n int; v_atid text; me digest.member_attributes;
  use_city boolean; use_state boolean; use_cat boolean; use_band boolean;
  use_model boolean; use_channel boolean;
  tgt_city text; tgt_state text; tgt_channel text; tgt_category text;
  target_mode boolean; trait_mode boolean;
begin
  select count(*) into v_n from digest.members m where m.phone = p_phone and digest.is_active_member_status(m.membership_status);
  if v_n <> 1 then return; end if;
  select m.at_member_id into v_atid from digest.members m where m.phone = p_phone and digest.is_active_member_status(m.membership_status);
  if v_atid is null then return; end if;
  select * into me from digest.member_attributes ma where ma.at_member_id = v_atid;
  if me is null then return; end if;

  tgt_city := digest.place_city(p_city);
  tgt_state := case when nullif(trim(coalesce(p_state, '')), '') is not null
                    then digest.attr_state(p_state) end;
  tgt_channel := nullif(trim(coalesce(p_channel, '')), '');
  tgt_category := nullif(trim(coalesce(p_category, '')), '');
  target_mode := tgt_city is not null or tgt_state is not null;
  trait_mode := tgt_channel is not null or tgt_category is not null;

  use_city    := not target_mode and 'city'  = any(p_dims) and me.city is not null;
  use_state   := not target_mode and 'state' = any(p_dims) and me.state is not null;
  use_cat     := not target_mode and tgt_category is null and 'category' = any(p_dims) and cardinality(me.categories) > 0;
  use_band    := not target_mode and 'band'     = any(p_dims) and me.rev_band is not null;
  use_model   := not target_mode and 'model'    = any(p_dims) and cardinality(me.business_model) > 0;
  use_channel := not target_mode and tgt_channel is null and 'channel' = any(p_dims) and cardinality(me.channel_mix) > 0;
  if not (target_mode or trait_mode or use_city or use_state or use_cat or use_band or use_model or use_channel) then return; end if;

  return query
  select ma.full_name, ma.city, ma.state,
    array_remove(array[
      case when target_mode and tgt_city is not null and ma.city ilike tgt_city
           then 'in ' || ma.city end,
      case when target_mode and not (tgt_city is not null and ma.city ilike tgt_city)
           then 'in ' || coalesce(ma.city || ' (' || ma.state || ')', ma.state) end,
      case when tgt_channel is not null and tgt_channel ilike '%tiktok%' and ma.tiktok_seller
           then 'sells on TikTok' end,
      case when tgt_channel is not null and not tgt_channel ilike '%tiktok%'
           then 'sells on ' || (select ch from unnest(ma.channel_mix) ch
                                where ch ilike '%' || tgt_channel || '%' limit 1) end,
      case when tgt_category is not null
           then 'category: ' || (select c from unnest(ma.categories) c
                                 where c ilike '%' || tgt_category || '%' limit 1) end,
      case when target_mode and ma.categories && me.categories then 'shared category: ' ||
        (select c from unnest(ma.categories) c where c = any(me.categories) limit 1) end,
      case when target_mode and ma.rev_band is not null and ma.rev_band = me.rev_band
           then 'similar revenue level' end,
      case when use_city  then 'same city' end,
      case when use_state then 'same state' end,
      case when use_cat and ma.categories && me.categories then 'shared category: ' ||
        (select c from unnest(ma.categories) c where c = any(me.categories) limit 1) end,
      case when use_band  then 'similar revenue level' end,
      case when use_model then 'similar business model' end,
      case when use_channel then 'also sells on ' ||
        (select ch from unnest(ma.channel_mix) ch where ch = any(me.channel_mix) limit 1) end
    ], null) as reasons
  from digest.member_attributes ma
  where ma.at_member_id <> v_atid
    and ma.full_name is not null
    and ma.membership_status in ('Current Member','New Member','Pending Group Entrance','Current Member- Not Renewing')
    and (not target_mode or (
          (tgt_city is not null and ma.city ilike tgt_city)
          or (tgt_state is not null and ma.state = tgt_state)))
    and (tgt_channel is null or (
          case when tgt_channel ilike '%tiktok%' then ma.tiktok_seller
               else exists (select 1 from unnest(ma.channel_mix) ch
                            where ch ilike '%' || tgt_channel || '%') end))
    and (tgt_category is null or exists (
          select 1 from unnest(ma.categories) c where c ilike '%' || tgt_category || '%'))
    and (not use_city    or lower(ma.city) = lower(me.city))
    and (not use_state   or lower(ma.state) = lower(me.state))
    and (not use_cat     or ma.categories && me.categories)
    and (not use_band    or ma.rev_band = me.rev_band)
    and (not use_model   or ma.business_model && me.business_model)
    and (not use_channel or ma.channel_mix && me.channel_mix)
  order by
    (target_mode and tgt_city is not null and ma.city ilike tgt_city) desc,
    (target_mode and (ma.categories && me.categories)) desc,
    (target_mode and ma.rev_band is not null and ma.rev_band = me.rev_band) desc,
    (lower(coalesce(ma.city, '')) = lower(coalesce(me.city, ''))) desc,
    ma.full_name
  limit greatest(coalesce(p_limit, 10), 0);
end $function$
